+using System.ComponentModel;
+using System.Net.Http.Json;
+using System.Text.Json;
+using Microsoft.Extensions.AI;
+using OpenAI;
+
+// --- Tool Implementations ---
+
+/// <summary>Provides web search capabilities via the Brave Search API.</summary>
+static class WebSearchTool
+{
+    private static readonly HttpClient s_http = new();
+
+    [Description("Search the web for information on a given query. Returns a list of result titles, URLs, and descriptions.")]
+    public static async Task<string> SearchWeb(
+        [Description("The search query string")] string query,
+        [Description("Max number of results to return (default 5)")] int count = 5)
+    {
+        var apiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");
+        if (string.IsNullOrEmpty(apiKey))
+            return "ERROR: BRAVE_API_KEY environment variable is not set. Cannot perform web search.";
+
+        try
+        {
+            var request = new HttpRequestMessage(HttpMethod.Get,
+                $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={count}");
+            request.Headers.Add("X-Subscription-Token", apiKey);
+            request.Headers.Add("Accept", "application/json");
+
+            var response = await s_http.SendAsync(request);
+            response.EnsureSuccessStatusCode();
+
+            using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
+            var results = doc.RootElement.GetProperty("web").GetProperty("results");
+
+            var output = new List<string>();
+            foreach (var r in results.EnumerateArray())
+            {
+                var title = r.GetProperty("title").GetString();
+                var url = r.GetProperty("url").GetString();
+                var desc = r.TryGetProperty("description", out var d) ? d.GetString() : "";
+                output.Add($"- **{title}**\n  URL: {url}\n  {desc}");
+            }
+
+            return output.Count > 0
+                ? string.Join("\n\n", output)
+                : "No results found.";
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}";
+        }
+    }
+}
+
+/// <summary>Provides note-taking capabilities so the agent can accumulate findings.</summary>
+static class NoteTakingTool
+{
+    private static readonly List<(string Topic, string Content)> s_notes = [];
+
+    [Description("Save a research note. Use this to record key findings, facts, or insights discovered during research.")]
+    public static string SaveNote(
+        [Description("A short topic or heading for this note")] string topic,
+        [Description("The detailed content of the note")] string content)
+    {
+        s_notes.Add((topic, content));
+        return $"Note #{s_notes.Count} saved under topic \"{topic}\".";
+    }
+
+    [Description("Retrieve all saved research notes.")]
+    public static string GetNotes()
+    {
+        if (s_notes.Count == 0)
+            return "No notes saved yet.";
+
+        return string.Join("\n\n", s_notes.Select((n, i) =>
+            $"--- Note #{i + 1}: {n.Topic} ---\n{n.Content}"));
+    }
+}
+
+// --- Main Program ---
+
+var topic = args.Length > 0
+    ? string.Join(' ', args)
+    : PromptForTopic();
+
+Console.WriteLine($"\n🔍 Researching: {topic}\n");
+
+var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
+    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
+
+var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
+
+IChatClient client = new OpenAIClient(apiKey)
+    .GetChatClient(model)
+    .AsIChatClient()
+    .AsBuilder()
+    .UseFunctionInvocation()
+    .Build();
+
+var tools = new AITool[]
+{
+    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
+    AIFunctionFactory.Create(NoteTakingTool.SaveNote),
+    AIFunctionFactory.Create(NoteTakingTool.GetNotes),
+};
+
+var chatOptions = new ChatOptions { Tools = [.. tools] };
+
+var messages = new List<ChatMessage>
+{
+    new(ChatRole.System, """
+        You are a research agent. Your job is to thoroughly research the given topic using web searches
+        and compile your findings into well-organized notes.
+
+        Follow this process:
+        1. Search the web for the topic to get an overview.
+        2. Save key findings as notes using the SaveNote tool.
+        3. Search for additional specific aspects or subtopics to get deeper information.
+        4. Save additional findings as notes.
+        5. Once you have gathered enough information (at least 3-4 notes), retrieve all your notes
+           and produce a final comprehensive summary.
+
+        Always cite sources with URLs when available. Be thorough but concise.
+        """),
+    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}"),
+};
+
+Console.ForegroundColor = ConsoleColor.DarkGray;
+
+await foreach (var update in client.GetStreamingResponseAsync(messages, chatOptions))
+{
+    if (update.Role == ChatRole.Assistant)
+        Console.Write(update.Text);
+}
+
+Console.ResetColor();
+Console.WriteLine("\n\n✅ Research complete.\n");
+
+static string PromptForTopic()
+{
+    Console.Write("Enter a research topic: ");
+    var input = Console.ReadLine()?.Trim();
+    return string.IsNullOrEmpty(input)
+        ? "Recent advances in quantum computing 2026"
+        : input;
+}

